import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import path from 'path';
import { log } from '../core/logger.js';
export function aboutCommand() {
    log.banner();
    const __dirname = path.dirname(fileURLToPath(import.meta.url));
    let version = '1.0.0';
    try {
        const packageJson = JSON.parse(readFileSync(path.resolve(__dirname, '../package.json'), 'utf8'));
        version = packageJson.version;
    }
    catch { }
    const colors = { bold: '\x1b[1m', dim: '\x1b[2m', cyan: '\x1b[36m', reset: '\x1b[0m' };
    console.log(`${colors.bold}WebAPKify${colors.reset} v${version}\n`);
    console.log(`  Wrap ${colors.cyan}any client-side web app${colors.reset} as a native Android APK.`);
    console.log(`  No Android Studio needed - just a JDK and an Android SDK.\n`);
    console.log(`${colors.bold}How it works${colors.reset}`);
    console.log(`  1. Reads ${colors.dim}webapkify.config.ts${colors.reset} from your project root`);
    console.log(`  2. Generates a complete Kotlin + Gradle Android project in ${colors.dim}./webapkify/${colors.reset}`);
    console.log(`  3. Copies your ${colors.dim}dist/${colors.reset} output into the Android asset bundle`);
    console.log(`  4. Runs Gradle (auto-bootstrapped wrapper) to compile the APK`);
    console.log(`  5. Drops ${colors.dim}<artifact>-debug.apk${colors.reset} / ${colors.dim}<artifact>-release.apk${colors.reset} in your project root\n`);
    console.log(`${colors.bold}Stack${colors.reset}`);
    console.log(`  Native   Kotlin + android.webkit.WebView (zero extra libs)`);
    console.log(`  Icons    Adaptive + Android 13+ monochrome themed icons (Sharp)`);
    console.log(`  Build    AGP 8.7 + Gradle 8.10 wrapper\n`);
}
